chrome.runtime.onInstalled.addListener(()=>{console.log("TransparentVideo Studio (BrowserOS) instalado con éxito."),chrome.contextMenus.create({id:"open-transparent-studio",title:"Abrir TransparentVideo Studio en pantalla completa",contexts:["action"]})});chrome.contextMenus.onClicked.addListener(e=>{e.menuItemId==="open-transparent-studio"&&chrome.tabs.create({url:chrome.runtime.getURL("studio/index.html")})});chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).catch(e=>console.error("Error al configurar SidePanel behavior:",e));chrome.runtime.onMessage.addListener((e,n,t)=>(e.action==="open_studio_tab"&&(chrome.tabs.create({url:chrome.runtime.getURL("studio/index.html")}),t({status:"ok"})),!0));
